-- Espejo de la función viva, ya aplicada. NO va en supabase/migrations.
-- ticket_es_real, tickets_so_num y el trigger tickets_zz_so_num.
-- No existe trg_tickets_so_vacio. No reescribas este archivo con otra versión.

CREATE OR REPLACE FUNCTION public.ticket_es_real(t tickets) RETURNS boolean LANGUAGE sql STABLE AS $function$ select t.timestamp is not null and ( coalesce(btrim(t.nombre),'') <> '' or coalesce(btrim(t.apellido),'') <> '' or coalesce(btrim(t.id_3::text),'') <> '' or coalesce(btrim(t.compra_pack_3::text),'') not in ('','false') or coalesce(btrim(t.compra_pack_6::text),'') not in ('','false') or coalesce(btrim(t.venta_gift::text),'') not in ('','false') or coalesce(btrim(t.servicios_adicionales::text),'') not in ('','false') or exists (select 1 from jsonb_each_text(to_jsonb(t)) e where e.key ~ '^(ht|as|ml|ph|jn|bv|su|vk)_[0-9]+$' and e.value ~ '^[0-9.]+$' and e.value::numeric > 0)) $function$;

CREATE OR REPLACE FUNCTION public.tickets_so_num() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if coalesce(new.origin,'') = 'test' then return new; end if; if not public.ticket_es_real(new) then if coalesce(new.origin,'') <> 'beta' then new.so_num := null; if new.orig ? 'so_num' then new.orig := new.orig - 'so_num'; end if; end if; return new; end if; if coalesce(new.so_num,'') !~ '^TK-SO-[0-9]+$' then if tg_op = 'UPDATE' and coalesce(old.so_num,'') ~ '^TK-SO-[0-9]+$' then new.so_num := old.so_num; elsif tg_op = 'INSERT' and new.sheet_row is not null and exists (select 1 from public.tickets x where x.sheet_row = new.sheet_row) then return new; else new.so_num := 'TK-SO-' || lpad(public.next_doc_num('TK-SO')::text, 4, '0'); end if; end if; if coalesce(new.orig->>'so_num','') <> new.so_num then new.orig := coalesce(new.orig,'{}'::jsonb) || jsonb_build_object('so_num', new.so_num); end if; return new; end $function$;

CREATE TRIGGER tickets_zz_so_num BEFORE INSERT OR UPDATE ON public.tickets FOR EACH ROW EXECUTE FUNCTION tickets_so_num();
